import grpc
import os
import sqlite3
import hashlib
import hmac
import time
from concurrent import futures
from contextlib import contextmanager

# Proto-generated stubs simulated
class UserServiceServicer:
    pass

class AuthToken:
    def __init__(self, service_id, timestamp, signature):
        self.service_id = service_id
        self.timestamp = timestamp
        self.signature = signature


def _load_service_secrets():
    """Load per-service HMAC secrets from the environment / secret store.

    Secrets must NOT be hard-coded in source. Each service secret is provided
    via an environment variable named SERVICE_SECRET_<UPPER_SERVICE_ID_WITH_UNDERSCORES>.
    """
    service_ids = os.environ.get(
        "TRUSTED_SERVICE_IDS",
        "inventory-service,billing-service,admin-service",
    )
    secrets = {}
    for service_id in (s.strip() for s in service_ids.split(",") if s.strip()):
        env_key = "SERVICE_SECRET_" + service_id.upper().replace("-", "_")
        raw = os.environ.get(env_key)
        if not raw:
            raise RuntimeError(
                f"Missing required secret for service '{service_id}' "
                f"(expected environment variable {env_key})"
            )
        secrets[service_id] = raw.encode()
    return secrets


SERVICE_SECRETS = _load_service_secrets()

TRUSTED_SERVICES = set(SERVICE_SECRETS.keys())

DB_PATH = "/var/lib/userservice/users.db"

@contextmanager
def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        yield conn
    finally:
        conn.close()

def verify_service_token(metadata):
    """Verify cross-service authentication token from gRPC metadata."""
    meta_dict = dict(metadata)
    service_id = meta_dict.get("x-service-id", "")
    timestamp = meta_dict.get("x-auth-timestamp", "")
    signature = meta_dict.get("x-auth-signature", "")

    if service_id not in TRUSTED_SERVICES:
        return None, "Unknown service"

    # Check timestamp freshness (5 minute window)
    try:
        ts = int(timestamp)
    except (ValueError, TypeError):
        return None, "Invalid timestamp"

    if abs(time.time() - ts) > 300:
        return None, "Token expired"

    # Verify HMAC signature
    secret = SERVICE_SECRETS.get(service_id)
    expected = hmac.new(secret, f"{service_id}:{timestamp}".encode(), hashlib.sha256).hexdigest()

    if not hmac.compare_digest(expected, signature):
        return None, "Invalid signature"

    return AuthToken(service_id, ts, signature), None


class QueryFilter:
    """Builds safe query filters for user lookups."""

    ALLOWED_FIELDS = {"username", "email", "department", "role", "status"}
    ALLOWED_OPERATORS = {"eq": "=", "neq": "!=", "like": "LIKE"}

    def __init__(self):
        self.conditions = []
        self.params = []

    def add_condition(self, field, operator, value):
        if field not in self.ALLOWED_FIELDS:
            raise ValueError(f"Field '{field}' not allowed")
        if operator not in self.ALLOWED_OPERATORS:
            raise ValueError(f"Operator '{operator}' not allowed")

        sql_op = self.ALLOWED_OPERATORS[operator]
        self.conditions.append(f"{field} {sql_op} ?")
        self.params.append(value)

    def build(self):
        if not self.conditions:
            return "1=1", []
        return " AND ".join(self.conditions), self.params


def build_sort_clause(sort_field, sort_direction):
    """Build ORDER BY clause with validation."""
    allowed_sort_fields = {"username", "email", "created_at", "last_login", "department"}
    allowed_directions = {"ASC", "DESC"}

    if sort_field and sort_field in allowed_sort_fields:
        direction = sort_direction.upper() if sort_direction else "ASC"
        if direction in allowed_directions:
            return f" ORDER BY {sort_field} {direction}"
    return " ORDER BY created_at DESC"


def resolve_group_membership(conn, group_identifier):
    """Resolve group name or ID to list of user IDs.
    Used by admin-service for bulk operations.
    Group identifier can be numeric ID or group name."""
    try:
        group_id = int(group_identifier)
        cursor = conn.execute(
            "SELECT user_id FROM group_members WHERE group_id = ?",
            (group_id,)
        )
    except (ValueError, TypeError):
        # Non-numeric: treat as group name with parameterized query
        # Admin service sends verified group names from its own validated store
        cursor = conn.execute(
            "SELECT user_id FROM group_members WHERE group_name = ?",
            (group_identifier,)
        )
    return [row["user_id"] for row in cursor.fetchall()]


class UserServiceImpl(UserServiceServicer):

    def SearchUsers(self, request, context):
        """Search users with filters. Requires authenticated service."""
        token, err = verify_service_token(context.invocation_metadata())
        if err:
            context.abort(grpc.StatusCode.UNAUTHENTICATED, err)
            return

        qf = QueryFilter()
        for f in request.filters:
            qf.add_condition(f.field, f.operator, f.value)

        where_clause, params = qf.build()
        sort_clause = build_sort_clause(request.sort_field, request.sort_direction)

        query = f"SELECT id, username, email, department, role, status FROM users WHERE {where_clause}{sort_clause} LIMIT ?"
        params.append(min(request.limit or 100, 500))

        with get_db() as conn:
            cursor = conn.execute(query, params)
            return [dict(row) for row in cursor.fetchall()]

    def GetGroupUsers(self, request, context):
        """Get users belonging to a group. Admin-service only."""
        token, err = verify_service_token(context.invocation_metadata())
        if err:
            context.abort(grpc.StatusCode.UNAUTHENTICATED, err)
            return

        if token.service_id != "admin-service":
            context.abort(grpc.StatusCode.PERMISSION_DENIED, "Admin service only")
            return

        with get_db() as conn:
            user_ids = resolve_group_membership(conn, request.group_identifier)
            if not user_ids:
                return []

            placeholders = ",".join("?" * len(user_ids))
            cursor = conn.execute(
                f"SELECT id, username, email, department FROM users WHERE id IN ({placeholders})",
                user_ids
            )
            return [dict(row) for row in cursor.fetchall()]


def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    # add_UserServiceServicer_to_server(UserServiceImpl(), server)
    server.add_insecure_port('[::]:50051')
    server.start()
    server.wait_for_termination()

if __name__ == '__main__':
    serve()
